WITH base AS (SELECT *, LAST_DAY(delivered_date) AS delivered_date_month_end FROM shipments WHERE carrier IS NOT NULL) SELECT id, order_id, carrier, shipped_date, delivered_date, cost, status, delivered_date_month_end, RANK() OVER (PARTITION BY order_id ORDER BY cost DESC NULLS LAST) AS cost_rank, AVG(cost) OVER (PARTITION BY status ORDER BY shipped_date ASC, id ASC ROWS BETWEEN 2 PRECEDING AND 1 PRECEDING) AS cost_avg_2_prior, ROUND(cost / SUM(cost) OVER (PARTITION BY status), 4) AS cost_share FROM base;
